using namespace moon;
timeline::State fixture(){timeline::State s;s.layers={{"layer",U"Layer"}};s.layers[0].groupId="inner";s.frames={{"f0",100},{"f1",175,true}};timeline::Group outer;outer.id="outer";outer.name=U"父组";outer.opacity=.7;outer.blendMode="screen";outer.panelOrder=.5;outer.displayColor=0x40112233;outer.description=U"备注";auto inner=outer;inner.id="inner";inner.name=U"子组";inner.parentGroupId="outer";inner.panelOrder.reset();inner.description.clear();inner.locked=true;s.groups={outer,inner};timeline::Cel c;c.id="owner";c.layerId="layer";c.frameId="f0";c.surface=timeline::Surface{2,1,-2,3,91,-73,{0x00030201,0xffabcdef}};s.cels.push_back(c);c.id="alias";c.frameId="f1";c.linkedCelId="owner";c.surface.reset();s.cels.push_back(c);return s;}
void model(){auto s=fixture();timeline::Timeline valid(s);CHECK(timeline::isLayerEffectivelyVisible(s,s.layers[0])&&timeline::isLayerEffectivelyLocked(s,s.layers[0]));s.groups[0].visible=false;CHECK(!timeline::isGroupEffectivelyVisible(s,s.groups[1])&&!timeline::isLayerEffectivelyVisible(s,s.layers[0]));auto reject=[](auto modify){auto s=fixture();modify(s);bool failed=false;try{timeline::Timeline bad(std::move(s));}catch(const std::invalid_argument&){failed=true;}CHECK(failed);};reject([](auto& s){s.groups[0].id="";});reject([](auto& s){s.groups[1].id="outer";});reject([](auto& s){s.groups[0].id="layer";});reject([](auto& s){s.groups[0].parentGroupId="missing";});reject([](auto& s){s.groups[0].parentGroupId="inner";});reject([](auto& s){s.groups[0].parentGroupId="outer";});reject([](auto& s){s.layers[0].groupId="missing";});reject([](auto& s){s.groups[0].opacity=2;});reject([](auto& s){s.groups[0].panelOrder=std::numeric_limits<double>::infinity();});reject([](auto& s){s.groups[0].blendMode="unsupported";});}
void io(const std::filesystem::path& root){std::filesystem::create_directories(root);Document base(3,4);const auto baseline=project::encodeEditableProject(base);auto d=Document::fromImported(3,4,fixture(),base.palette(),baseline.projectId,U"Group fixture",baseline.bytes);d.clearSourceArchiveForNewSnapshot();d.markRecovered(d.name());const auto history=d.historySize(),revision=d.revision();DocumentSnapshot snapshot(d);while(!snapshot.advance(d,std::chrono::steady_clock::now()+std::chrono::seconds(1))){}auto copy=snapshot.finish();CHECK(copy.timeline().state().groups.size()==2&&copy.timeline().state().layers[0].groupId==std::optional<std::string>("inner"));
 for(bool recovery:{false,true}){const auto encoded=recovery?project::encodeRecoveryProject(copy):project::encodeEditableProject(copy);const auto path=root/(recovery?"internal-group-recovery.moonsprite":"internal-group.moonsprite");std::ofstream out(path,std::ios::binary);out.write(reinterpret_cast<const char*>(encoded.bytes->data()),std::streamsize(encoded.bytes->size()));out.close();std::ifstream in(path,std::ios::binary);auto disk=std::make_shared<const project::Bytes>(std::istreambuf_iterator<char>(in),std::istreambuf_iterator<char>());auto m=project::readProjectManifest(disk);CHECK(m.groups.size()==2&&m.groups[0].id=="outer"&&m.groups[0].name=="父组"&&m.groups[0].panelOrder==.5&&m.groups[0].displayColor==0x40112233&&m.groups[0].description=="备注"&&m.groups[0].opacity==.7&&m.groups[0].blendMode=="screen"&&m.groups[1].parentGroupId=="outer"&&!m.groups[1].panelOrder&&m.groups[1].locked&&m.layers[0].groupId=="inner"&&m.cels[0].surface->pixels[0]==0x00030201);auto admitted=project::prepareEditableImport(m);CHECK(admitted.timeline.groups.size()==2&&admitted.timeline.layers[0].groupId=="inner");}
 const auto sentinel=root/"save-admission.moonsprite";{std::ofstream out(sentinel,std::ios::binary);out<<"preserved";}project::saveDocumentAtomic(d,sentinel);std::ifstream in(sentinel,std::ios::binary);auto bytes=std::make_shared<const project::Bytes>(std::istreambuf_iterator<char>(in),std::istreambuf_iterator<char>());auto saved=project::prepareEditableImport(project::readProjectManifest(bytes));CHECK(saved.timeline.groups.size()==2&&d.revision()==revision&&d.historySize()==history);auto altered=fixture();RasterSnapshot raster(altered);altered.groups[0].description=U"changed";CHECK(!raster.matches(altered));altered=fixture();altered.layers[0].groupId="outer";CHECK(!raster.matches(altered));
}
void inheritedEditing(){
 auto make=[](bool visible,bool locked){timeline::State s;s.layers={{"a",U"A"},{"b",U"B"}};s.layers[0].groupId="g";timeline::Group g;g.id="g";g.name=U"Group";g.visible=visible;g.locked=locked;s.groups={g};s.frames={{"f0",100},{"f1",100}};for(const auto& l:s.layers)for(const auto& f:s.frames){timeline::Cel c;c.id=l.id+f.id;c.layerId=l.id;c.frameId=f.id;c.surface=timeline::Surface{2,1,0,0,{},{},{l.id=="a"?0xff112233u:0xff556677u,0}};s.cels.push_back(c);}Document base(2,1);auto d=Document::fromImported(2,1,std::move(s),base.palette(),"editing-groups",U"Group editing",std::make_shared<const std::vector<std::uint8_t>>());d.clearSourceArchiveForNewSnapshot();return d;};
 for(const auto flags:{std::pair{false,false},std::pair{true,true}}){auto d=make(flags.first,flags.second);const auto before=d.pixels();const auto history=d.historySize(),revision=d.revision();CHECK(!d.rasterToolsAvailable());d.beginStroke({0,0},0xffabcdef);d.commitStroke();CHECK(!d.fillSelectionOrCanvas(0xffabcdef));CHECK(!d.beginGradient({0,0},{}));CHECK(!d.beginShapePreview());CHECK(d.pixels()==before&&d.historySize()==history&&d.revision()==revision);}
 auto d=make(true,false);CHECK(d.rasterToolsAvailable());d.beginStroke({0,0},0xffabcdef);d.commitStroke();CHECK(d.pixels()[0]==0xffabcdef&&d.historySize()==1);d.undo();CHECK(d.pixels()[0]==0xff112233);
 auto locked=make(true,true);const auto source=prepareCrossfadeTweenSource(locked.timeline(),"f0","a",TweenLayerScope::All);CHECK(source.layerIds==std::vector<std::string>{"b"});
 auto hidden=make(false,false);const auto all=prepareCrossfadeTweenSource(hidden.timeline(),"f0","a",TweenLayerScope::All);CrossfadeTweenOptions options;options.frameCount=1;CHECK(compositeCrossfadeTweenPreview(hidden.timeline(),2,1,all,options,1)[0]==0xff556677);
}
void groupCommandTargets(){
 timeline::State s;s.layers={{"a",U"A"},{"b",U"B"},{"outside",U"Outside"}};s.layers[0].groupId=s.layers[1].groupId="g";timeline::Group g;g.id="g";g.name=U"Group";s.groups={g};s.frames={{"f",100}};
 for(const auto& l:s.layers){timeline::Cel c;c.id=l.id+"/f";c.layerId=l.id;c.frameId="f";c.surface=timeline::Surface{2,1,l.id=="b"?-1:1,1,{},{},{0xff112233,0x00030201}};s.cels.push_back(c);}
 Document base(4,3);auto d=Document::fromImported(4,3,std::move(s),base.palette(),"group-targets",U"Group targets",std::make_shared<const std::vector<std::uint8_t>>());d.clearSourceArchiveForNewSnapshot();d.selectTimelineRow({LayerPanelKind::Group,"g",0});const auto outside=*d.timeline().resolveSurface("outside/f").surface;const auto beforeA=*d.timeline().resolveSurface("a/f").surface,beforeB=*d.timeline().resolveSurface("b/f").surface;const auto history=d.historySize();CHECK(d.fillSelectionOrCanvas(0xffabcdef));CHECK(d.historySize()==history+1);
 for(const auto* id:{"a/f","b/f"})for(int y=0;y<3;++y)for(int x=0;x<4;++x)CHECK(raster::readWorld(*d.timeline().resolveSurface(id).surface,x,y)==0xffabcdef);
 CHECK(d.timeline().resolveSurface("outside/f").surface->pixels==outside.pixels);d.undo();CHECK(d.timeline().resolveSurface("a/f").surface->pixels==beforeA.pixels&&d.timeline().resolveSurface("a/f").surface->offsetX==beforeA.offsetX);CHECK(d.timeline().resolveSurface("b/f").surface->pixels==beforeB.pixels&&d.timeline().resolveSurface("b/f").surface->offsetX==beforeB.offsetX);d.redo();CHECK(raster::readWorld(*d.timeline().resolveSurface("b/f").surface,3,2)==0xffabcdef);d.undo();
 d.setGroupLocked("g",true);const auto lockedHistory=d.historySize();CHECK(!d.fillSelectionOrCanvas(0xff334455));CHECK(d.historySize()==lockedHistory&&d.timeline().resolveSurface("a/f").surface->pixels==beforeA.pixels);
}
